INSERT INTO `rules` (`id`, `rule_text`, `rule_order`, `created_at`, `updated_at`) VALUES
(1, '=== only classic Rooms valid on our group', 0, '2025-07-07 09:51:07', '2025-07-07 09:51:07'),
(2, 'BINA WIN SCREENSHOT KOI WINNING NHI', 1, '2025-07-07 09:51:31', '2025-07-07 09:51:31'),
(3, 'Admin Ka Decision Final Hoga , Agar aap isse agree nhi ho to aapko baki rules pdhne ki jrurt nhi , Group abhi left krr skte ho , kyunki Sbko sahi trike se hi khelna hoga ?', 2, '2025-07-07 09:51:49', '2025-07-07 09:51:49'),
(4, 'Game Ke bich me kisi bhi reason se left karne pe aap hare mane jaoge ( Battery low , network problem , call ka aana ya dusra koi bhi reason ho agar aap left kroge to aap apna hi nuksan kroge', 3, '2025-07-07 09:52:38', '2025-07-07 09:52:38'),
(5, 'Agar aapki geeti open nhi hui h aur samne wala left krta to. Game Cancle .', 4, '2025-07-07 09:52:53', '2025-07-07 09:52:53'),
(6, 'Agar samne wale player ke dice pe six aaya hai aur aap game left krdete ho uski geeti open krne se pehle to aapka 20% Cut hoga isliye ye chalaki nhi chlegi ( 20% harjana bharna pdega samne wale ko', 5, '2025-07-07 09:53:25', '2025-07-07 09:53:25'),
(7, 'Agar Aapki kisi bhi wajah se aap Game ki shuruvat me hi left krdete ho  , Aur apke sath khel rahe player ki geeti open ho jati h ya aapke home tak aajati hai uss condition me Aapki aadhi winning Cut hogi , agar geeti aapke ghr se aage hogi uski to full winning milegi usko ) isliye dhiyan dein', 6, '2025-07-07 09:53:53', '2025-07-07 09:53:53'),
(8, 'Sab Geeti andar jane pe agar player auto pe geeti chorrta h to table amount ka 20% less ho jayega', 8, '2025-07-07 09:55:13', '2025-07-07 09:55:13'),
(9, 'Agar Kisi bhi player ne Dusre player ki geeti ek bar bhi cut ki hai aur fir samne wala left kardeta hai to bhi poori winning winner ko milegi', 9, '2025-07-07 09:55:40', '2025-07-07 09:55:40'),
(10, '1g/2g game me uper likhe sabhi rules valid nhi hain .... Ek hi rule hai ... Geeti agar samne wale player ki open hui aur aap left krte ho to aap loss ..', 9, '2025-07-07 09:55:59', '2025-07-07 09:55:59'),
(11, 'Code exchange ke baad agar code delete krdoge aur ye claim kroge ki khele nhi ho aur opponent ye screenshot dedega jisme \"Message delete\" likha hoga to Sari dp zero krke bahar krdiyye jaoge.', 10, '2025-07-07 09:56:22', '2025-07-07 09:56:22'),
(12, 'Group me badtameezi krne se admin ke pas poora haq hai aapka balance zero karke aapko remove krdene ka  ( Don\'t use bad language in group )', 11, '2025-07-07 09:56:39', '2025-07-07 09:56:39'),
(13, 'Slow khelo ya fast ye players ki marji rhegi wo kese khelega , isliye ek dusre ko gali na dein ....jiske sath mann kre uske sath fix krein .', 11, '2025-07-07 09:56:56', '2025-07-07 09:56:56'),
(14, 'code len den pe jyada behas na krein .... Equality bnaye rkhein ....ek bar code dein aur ek bar samne wale se lein .', 12, '2025-07-07 09:57:15', '2025-07-07 09:57:15'),
(15, '10 Se jyada games wali id ko frash id nhi mana jayega ,', 14, '2025-07-07 09:57:35', '2025-07-07 09:57:35'),
(16, 'S N A K E \r\n---------------- \r\nSNAKE ME AGAR KOI  LEFT KRTA HAI TO WIN AAPKO TABHI MILEGI JAB AAPKI GEETI YA TO 50 NUMBER SE UPER HO YA WIN SCREENSHOT PE AAP KOI STAIR CHDE HO / SNAKE SE KATE GYE HO', 15, '2025-07-07 09:57:57', '2025-07-07 09:57:57'),
(17, '? FAKE PAYMENT & WIN SCREENSHOT BHEJNE PE ALL DP ZERO and Removed ?', 16, '2025-07-07 09:58:49', '2025-07-07 09:58:49');

