--
-- Table structure for table `sl_games`
--

CREATE TABLE `sl_games` (
  `id` int(11) NOT NULL,
  `room_id` int(11) NOT NULL,
  `player1_id` int(11) NOT NULL,
  `player2_id` int(11) NOT NULL,
  `player1_pos` tinyint(4) DEFAULT 0,
  `player2_pos` tinyint(4) DEFAULT 0,
  `current_turn` int(11) NOT NULL,
  `dice_value` tinyint(4) DEFAULT NULL,
  `dice_rolled` tinyint(1) DEFAULT 0,
  `consecutive_six` tinyint(4) DEFAULT 0,
  `winner_id` int(11) DEFAULT NULL,
  `status` enum('active','completed','cancelled') DEFAULT 'active',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `prev_p1_pos` tinyint(4) DEFAULT 0,
  `prev_p2_pos` tinyint(4) DEFAULT 0,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

